import { encodeCsvField } from './csv-field.mjs';

export function parseCsv(text) {
  if (typeof text !== 'string') {
    throw new TypeError('parseCsv expects a string');
  }
  if (text.length === 0) {
    return [];
  }

  const rows = [];
  let row = [];
  let field = '';
  let i = 0;
  const n = text.length;

  const pushRow = () => {
    row.push(field);
    field = '';
    rows.push(row);
    row = [];
  };

  while (i < n) {
    const c = text[i];

    if (c === '"') {
      if (field.length !== 0) {
        throw new SyntaxError('Invalid quote in unquoted field');
      }
      i += 1;
      let closed = false;
      while (i < n) {
        if (text[i] === '"') {
          if (i + 1 < n && text[i + 1] === '"') {
            field += '"';
            i += 2;
            continue;
          }
          i += 1;
          closed = true;
          break;
        }
        field += text[i];
        i += 1;
      }
      if (!closed) {
        throw new SyntaxError('Unclosed quoted field');
      }
      if (i < n) {
        const after = text[i];
        if (after === ',') {
          row.push(field);
          field = '';
          i += 1;
          continue;
        }
        if (after === '\r') {
          i += 1;
          if (i < n && text[i] === '\n') {
            i += 1;
          }
          row.push(field);
          field = '';
          rows.push(row);
          row = [];
          continue;
        }
        if (after === '\n') {
          i += 1;
          row.push(field);
          field = '';
          rows.push(row);
          row = [];
          continue;
        }
        throw new SyntaxError('Invalid character after quoted field');
      }
      continue;
    }

    if (c === ',') {
      row.push(field);
      field = '';
      i += 1;
      continue;
    }

    if (c === '\r') {
      i += 1;
      if (i < n && text[i] === '\n') {
        i += 1;
      }
      pushRow();
      continue;
    }

    if (c === '\n') {
      i += 1;
      pushRow();
      continue;
    }

    field += c;
    i += 1;
  }

  if (field.length !== 0 || row.length !== 0) {
    row.push(field);
    rows.push(row);
  }

  return rows;
}

export function serializeCsv(rows) {
  if (!Array.isArray(rows)) {
    throw new TypeError('serializeCsv expects an array');
  }
  for (const row of rows) {
    if (!Array.isArray(row) || row.length === 0) {
      throw new TypeError('Invalid row');
    }
    for (const cell of row) {
      if (typeof cell !== 'string') {
        throw new TypeError('Invalid field');
      }
    }
  }
  return rows.map((row) => row.map(encodeCsvField).join(',')).join('\r\n');
}

